\caption{Estimates for each reward probability based on the knowledge that machine $A$ was played $N_A$ times and that machine $B$ was played $N_B$ times---on the assumption that the sum of the reward probabilities $\gamma$ $=$ $P_A$ $+$ $P_B$ is known.}
\label{table:1}
\begin{center}
\begin{tabular}{|c|c|c|c|}\hline \hline
$A$: & $\frac{N_A - L_A}{N_A}$ & $B$: & $\gamma \hspace{1mm} -$ $\frac{N_A - L_A}{N_A}$ \\ \hline
$A$: & $\gamma \hspace{1mm} -$ $\frac{N_B - L_B}{N_B}$ & $B$: & $\frac{N_B - L_B}{N_B}$ \\ \hline
\end{tabular}
\end{center}

In addition, the essence of the process described here can be generalized to $M$-machine cases.
To separate distributions of the top $m$-th and top $(m+1)$-th machine, as shown in Fig.~\ref{fig:random}(b), all we need is the following $\omega_0$:
\begin{eqnarray}
\omega_0  & = & \frac{\gamma^{\prime}}{2 - \gamma^{\prime}} , \\
\gamma^{\prime} & = & P_{(m)} + P_{(m+1)}
\end{eqnarray} 
Here, $P_{(m)}$ denotes the top $m$-th reward probability.
In fact, for $M$-machine and $X$-player cases, we have designed a physical system that can  determine the overall optimal state, called the ``social maximum,'' quickly and accurately~\cite{bom}.

From the above estimates, each expected reward $Q^{\prime}_k$ ($k\in \{A,B\}$) is given as follows:
\begin{eqnarray}
Q^{\prime}_A & = & N_A \hspace{1mm} \frac{N_A - L_A}{N_A} + N_B \hspace{1mm} \bigl( \gamma \hspace{1mm} - \frac{N_B - L_B}{N_B} \bigr) \nonumber \\
 & = & N_A - L_A + (\gamma - 1) \hspace{1mm} N_B + L_B, \label{eq:qAp}\\
Q^{\prime}_B & = & N_A\hspace{1mm} \bigl( \gamma \hspace{1mm} - \frac{N_A - L_A}{N_A} \bigr) + N_B\hspace{1mm} \frac{N_B - L_B}{N_B} \nonumber \\
& = & N_B - L_B + (\gamma - 1) \hspace{1mm} N_A + L_A. \label{eq:qBp}
\end{eqnarray}
These expected rewards, $Q^{\prime}_j$s, are not the same as those given by the learning rules of TOW dynamics, $Q_j$s in Eq.(\ref{eq:org}).  
However, what we use substantially in TOW dynamics is the difference
\begin{equation}
Q_A - Q_B  =  (N_A - N_B) - (1 + \omega)\hspace{1mm}(L_A - L_B)\label{eq:dq}.
\end{equation}
When we transform the expected rewards $Q^{\prime}_j$s into $Q^{\prime \prime}_j  =  Q^{\prime}_j / (2 - \gamma)$,

\begin{eqnarray}
\omega_0 & = & \frac{\gamma}{2 - \gamma} , \label{eq:w0}\\
\gamma & = & P_A + P_B .
\end{eqnarray}

\begin{eqnarray}
P(t=N+1,B) & = & {\bf Q}(\phi \sqrt{N}) .
\end{eqnarray}

\begin{equation}
Q_A - Q_B  =  (N_A - N_B) - (1 + \omega)\hspace{1mm}(L_A - L_B)\label{eq:dq}.
\end{equation}

\begin{equation}
E( R_k(t) ) = \{\alpha P_k - \beta (1 - P_k)\}\hspace{1mm} N_k .
\end{equation}

\begin{equation}
P_B  < \frac{\beta}{\alpha + \beta}   < P_A .  \label{eq:cond1}
\end{equation}

\begin{equation}
\frac{\beta}{\alpha + \beta}   = \frac{P_A + P_B}{2} .\label{eq:fixed}
\end{equation}

\begin{equation}
Q^{\prime \prime}_A - Q^{\prime \prime}_B  =  (N_A - N_B) - \frac{2}{2-\gamma} \hspace{1mm} (L_A - L_B). \label{eq:dqpp}
\end{equation}

\begin{equation}
regret = (\mu_A - \mu_B) E(N_B).
\end{equation}
